local KEYBOARD_ROWS = {
	{ "z", "x", "c", "v", "b", "n", "m" },
	{ "s", "d", "g", "h", "j" },
	{ "q", "w", "e", "r", "t", "y", "u", "i", "o", "p" },
	{ "2", "3", "5", "6", "7", "9", "0" },
}

local DIGIT_NAMES = {
	["0"] = "Zero", ["1"] = "One", ["2"] = "Two", ["3"] = "Three", ["4"] = "Four",
	["5"] = "Five", ["6"] = "Six", ["7"] = "Seven", ["8"] = "Eight", ["9"] = "Nine",
}
local keyCodeCache = {}

local function resolveKeyCode(key)
	local cached = keyCodeCache[key]
	if cached ~= nil then
		return cached or nil
	end
	local name = DIGIT_NAMES[key] or key:upper()
	local ok, code = pcall(function() return Enum.KeyCode[name] end)
	keyCodeCache[key] = (ok and code) or false
	return (ok and code) or nil
end

local SHIFT_SYMBOLS = {
	["!"] = "1", ["@"] = "2", ["#"] = "3", ["$"] = "4", ["%"] = "5",
	["^"] = "6", ["&"] = "7", ["*"] = "8", ["("] = "9", [")"] = "0",
}

local function keyInfo(key)
	local base, shifted = key, false
	if SHIFT_SYMBOLS[key] then
		base, shifted = SHIFT_SYMBOLS[key], true
	elseif key:match("%u") then
		base, shifted = key:lower(), true
	end
	return resolveKeyCode(base), shifted
end

local function isKeyChar(c)
	return c:match("^%w$") ~= nil or SHIFT_SYMBOLS[c] ~= nil
end

