for _, song in ipairs(SONGS) do
	if song.encoded and not song.sheet then
		local parts = {}
		for line in song.encoded:gmatch("[^\n]+") do
			local _, keyString = line:match("^(%S+) (%S+)")
			if keyString then
				parts[#parts + 1] = keyString
			end
		end
		song.sheet = table.concat(parts)
	end
end

-- State.
local currentSong = nil
local isPlaying = false
local stopRequested = false
local playbackThread = nil
local inputContext = nil
local keyBoxes = {}
local guiRefs = {}

if shared.HeavenPiano then
	pcall(function() shared.HeavenPiano.destroy() end)
end

local function tokenize(sheet, song)
	local spaceSteps = song and song.spaceSteps or 0
	local pipeSteps = song and song.pipeSteps or 0
	local tokens = {}
	local function addRests(n)
		for _ = 1, n do
			tokens[#tokens + 1] = { rest = true }
		end
	end
	local i = 1
	while i <= #sheet do
		local c = sheet:sub(i, i)
		if c == "[" then
			local j = sheet:find("]", i, true)
			if not j then break end
			local keys = {}
			for k = i + 1, j - 1 do
				local key = sheet:sub(k, k)
				if isKeyChar(key) then
					keys[#keys + 1] = key
				end
			end
			if #keys > 0 then
				tokens[#tokens + 1] = { keys = keys }
			end
			i = j + 1
		elseif c == "-" then
			addRests(1)
			i = i + 1
		elseif c == "|" then
			addRests(pipeSteps)
			i = i + 1
		elseif c == " " then
			addRests(spaceSteps)
			i = i + 1
		elseif isKeyChar(c) then
			tokens[#tokens + 1] = { keys = { c } }
			i = i + 1
		else
			i = i + 1
		end
	end
	return tokens
end

local function buildEncodedEvents(song, speed)
	local events = {}
	for line in song.encoded:gmatch("[^\n]+") do
		local time, keyString, hold = line:match("^(%S+) (%S+) ?(%S*)$")
		if time then
			local keys = {}
			for k = 1, #keyString do
				keys[k] = keyString:sub(k, k)
			end
			events[#events + 1] = {
				time = tonumber(time) / speed,
				keys = keys,
				unit = 0.12 / speed,
				fixedHold = tonumber(hold) and tonumber(hold) / speed or nil,
			}
		end
	end
	return events
end

local function buildNoteArray(song, phaseOffset, speed)
	local tokens = song.encoded and {} or tokenize(song.sheet, song)
	local events = {}
	local time = 0
	local baseUnit = song.bpm and (60 / song.bpm / (song.stepsPerBeat or 4)) or 0.25

	for step, token in ipairs(tokens) do
		local unit = baseUnit / speed
		if token.keys then
			events[#events + 1] = { time = time, keys = token.keys, unit = unit }
		end
		time = time + unit
	end

	if song.encoded then
		events = buildEncodedEvents(song, speed)
	end

	for n = 1, #events - 1 do
		local gap = events[n + 1].time - events[n].time
		if gap > events[n].unit * CONFIG.phraseGapRatio then
			events[n].phraseEnd = true
		end
	end
	if #events > 0 then
		events[#events].phraseEnd = true
	end

	local maxHold = song.maxHold or CONFIG.maxHold
	local holdRatio = song.holdGapRatio or CONFIG.holdGapRatio
	for n = 1, #events do
		local nextTime = events[n + 1] and events[n + 1].time or (events[n].time + events[n].unit)
		local gap = nextTime - events[n].time
		local hold = math.clamp(gap * holdRatio, CONFIG.minHold, maxHold)
		if events[n].phraseEnd then
			hold = math.min(hold + CONFIG.phraseLingerHold, maxHold)
		end
		local lift = math.min(CONFIG.releaseBeforeNext, gap * 0.3)
		hold = math.min(hold, math.max(gap - lift, 0.03))
		if n == #events then
			hold = maxHold
		end
		if events[n].fixedHold then
			hold = events[n].fixedHold
		end
		events[n].hold = hold
	end

	return events
end

local function extractKeys(sheet)
	local seen, ordered = {}, {}
	local function add(key)
		if isKeyChar(key) and not seen[key] then
			seen[key] = true
			ordered[#ordered + 1] = key
		end
	end
	local i = 1
	while i <= #sheet do
		local c = sheet:sub(i, i)
		if c == "[" then
			local j = sheet:find("]", i, true)
			if not j then break end
			for k = i + 1, j - 1 do
				add(sheet:sub(k, k))
			end
			i = j + 1
		else
			add(c)
			i = i + 1
		end
	end
	return ordered
end

local function vimKey(key, isDown)
	local keyCode, shifted = keyInfo(key)
	if not keyCode then return end
	pcall(function()
		if shifted then
			virtualInputManager:SendKeyEvent(true, Enum.KeyCode.LeftShift, false, game)
		end
		virtualInputManager:SendKeyEvent(isDown, keyCode, false, game)
		if shifted then
			virtualInputManager:SendKeyEvent(false, Enum.KeyCode.LeftShift, false, game)
		end
	end)
end

local function findPianoRemote()
	local patterns = { "piano", "note", "play", "key", "music", "sound", "instrument", "press" }
	for _, desc in ipairs(replicatedStorage:GetDescendants()) do
		if desc:IsA("RemoteEvent") or desc:IsA("RemoteFunction") then
			local lower = desc.Name:lower()
			for _, p in ipairs(patterns) do
				if lower:find(p, 1, true) then return desc end
			end
		end
	end
	return nil
end

local function formatRemoteKey(key)
	if CONFIG.remoteKeyFormat == "lower" then return key:lower() end
	if CONFIG.remoteKeyFormat == "upper" then return key:upper() end
	return key
end

local function fireRemote(key)
	if not inputContext or not inputContext.target then return end
	local formatted = formatRemoteKey(key)
	pcall(function()
		if inputContext.target:IsA("RemoteEvent") then
			inputContext.target:FireServer(formatted)
		elseif inputContext.target:IsA("RemoteFunction") then
			inputContext.target:InvokeServer(formatted)
		end
	end)
end

local function isTouchPlatform()
	if CONFIG.platform == "touch" then return true end
	if CONFIG.platform == "keyboard" then return false end
	return userInputService.TouchEnabled and not userInputService.KeyboardEnabled
end

-- Phone/tablet: the piano keys are on-screen buttons under PianoUI.MobilePianoContainer.
local function getTouchKeys()
	local pianoUI = localPlayer.PlayerGui:FindFirstChild("PianoUI")
	local container = pianoUI and pianoUI:FindFirstChild("MobilePianoContainer")
	local keyFrame = container and container:FindFirstChild("KeyFrame")
	if not keyFrame then return nil end
	local map = {}
	for _, child in ipairs(keyFrame:GetChildren()) do
		local label = child:FindFirstChild("Label")
		if label and (label:IsA("TextLabel") or label:IsA("TextButton")) and label.Text ~= "" then
			local button = child:IsA("GuiButton") and child or child:FindFirstChildWhichIsA("GuiButton", true)
			map[label.Text] = button or child
		end
	end
	if next(map) == nil then return nil end
	return map
end

local function pressSignal(signal)
	if firesignal then
		pcall(firesignal, signal)
		return
	end
	local ok, conns = pcall(getconnections, signal)
	if ok and conns then
		for _, conn in ipairs(conns) do
			pcall(function() conn:Fire() end)
		end
	end
end

-- Presses or releases one on-screen key. Buttons get their press/release events directly,
-- so the item bar that overlaps the lower keys does not get the tap.
local touchDownAt = {}

local function touchKey(obj, isDown)
	if not obj then return end
	pcall(function()
		if obj:IsA("GuiButton") then
			pressSignal(isDown and obj.MouseButton1Down or obj.MouseButton1Up)
			return
		end
		-- A release goes to the same spot as its press, even if the key has moved or been removed.
		local spot = touchDownAt[obj]
		if isDown or not spot then
			local sg = obj:FindFirstAncestorWhichIsA("ScreenGui")
			local inset = (sg and sg.IgnoreGuiInset) and 0 or guiService:GetGuiInset().Y
			spot = {
				x = obj.AbsolutePosition.X + obj.AbsoluteSize.X / 2,
				y = obj.AbsolutePosition.Y + obj.AbsoluteSize.Y / 2 + inset,
			}
		end
		touchDownAt[obj] = isDown and spot or nil
		virtualInputManager:SendMouseButtonEvent(spot.x, spot.y, 0, isDown, game, 0)
	end)
end

local function probeInputContext()
	if isTouchPlatform() then
		local keys = getTouchKeys()
		if keys then
			return { type = "touch", keys = keys }
		end
		-- No piano buttons here (not the Relapse layout): use the usual keyboard method.
	end
	if CONFIG.inputMethod == "vim" then return { type = "vim" } end
	if CONFIG.inputMethod == "remote" then
		return { type = "remote", target = findPianoRemote() }
	end
	return { type = "vim" }
end

local keyLit = {}

-- Lights a keyboard key only while the script is holding it.
local function setKeyVisual(key, lit)
	keyLit[key] = lit or nil
	local cap = keyBoxes[key]
	if not cap then
		return
	end
	local on = keyLit[cap.white] == true or keyLit[cap.sharp] == true
	cap.face.BackgroundColor3 = on and KEY_ACTIVE or KEY_IDLE
	cap.stroke.Enabled = on
end

local function pressKey(key)
	if not inputContext then return end
	if inputContext.type == "vim" then vimKey(key, true)
	elseif inputContext.type == "remote" then fireRemote(key)
	elseif inputContext.type == "touch" then touchKey(inputContext.keys and inputContext.keys[key], true) end
end

local function releaseKey(key)
	setKeyVisual(key, false)
	if not inputContext then return end
	if inputContext.type == "vim" then vimKey(key, false)
	elseif inputContext.type == "touch" then touchKey(inputContext.keys and inputContext.keys[key], false) end
end

local keyDown = {}
local releaseAt = {}
local pressCounter = 0
local pendingPress = {}
local heartbeatConn = nil

local function pressAndSchedule(key, releaseTime)
	if keyDown[key] then
		releaseKey(key)
	end
	pressCounter = pressCounter + 1
	local pressId = pressCounter
	keyDown[key] = pressId
	pressKey(key)
	setKeyVisual(key, true)
	releaseAt[key] = { at = releaseTime, id = pressId }
end

-- Playback position, pause state and the note sheet that picks where playback starts.
local paused = false
local pausedAt = 0
local playClock = 0 -- timeline = os.clock() - playClock
local playNextIndex = 1
local playEvents = {}
local playEventsSong = nil
local playRow = nil -- sheet row of the playhead while playing or paused
local sheetSelected = 1 -- sheet row playback starts from when stopped
local sheetButtons = {}
local glowStroke = nil
local glowTween = nil
local lastStatusAt = 0

local SHEET_ROW_H = 20
local SHEET_ROW_STEP = 22 -- row height plus the 2px list padding
local SHEET_IDLE = Color3.fromRGB(255, 255, 255)
local SHEET_GLOW = Color3.fromRGB(255, 226, 140)
local SHEET_GLOW_EDGE = Color3.fromRGB(255, 176, 40)

local function getPlayEvents(song)
	if playEventsSong ~= song then
		local events = buildNoteArray(song, 0, CONFIG.speed)
		for _, event in ipairs(events) do
			event.fireAt = event.time
		end
		playEvents = events
		playEventsSong = song
	end
	return playEvents
end

-- Index of the first event that starts at or after t seconds.
local function firstEventAtOrAfter(events, t)
	for i, event in ipairs(events) do
		if event.fireAt >= t then
			return i
		end
	end
	return #events + 1
end

local function rowTime(row)
	return math.max((row or 1) - 1, 0)
end

local function clockText(seconds)
	local s = math.max(seconds, 0)
	return string.format("%d:%04.1f", math.floor(s / 60), s % 60)
end

local function setStatus(text)
	if guiRefs.status then
		guiRefs.status.TextTransparency = 0
		guiRefs.status.Text = text
	end
end

local function releaseAllKeys()
	for key in pairs(keyDown) do
		keyDown[key] = nil
		releaseKey(key)
	end
	if inputContext and inputContext.type == "vim" then
		for key, cap in pairs(keyBoxes) do
			if key == cap.white then
				releaseKey(key)
			end
		end
	end
	releaseAt = {}
	pendingPress = {}
end

local function refreshControls()
	if guiRefs.playButton then
		guiRefs.playButton.Text = (isPlaying and not paused) and "Playing..." or "Play"
	end
	if guiRefs.pauseButton then
		guiRefs.pauseButton.Text = paused and "Resume" or "Pause"
	end
end

-- Scrolls only when the row has left the visible part, so manual scrolling is not fought.
local function keepRowVisible(row)
	local sheet = guiRefs.sheet
	if not sheet or not row then
		return
	end
	local viewH = sheet.Size.Y.Offset -- logical height, same units as CanvasPosition
	if viewH <= 0 then
		return
	end
	local top = (row - 1) * SHEET_ROW_STEP
	local bottom = top + SHEET_ROW_H
	local viewTop = sheet.CanvasPosition.Y
	if top < viewTop or bottom > viewTop + viewH then
		sheet.CanvasPosition = Vector2.new(0, math.max(top - viewH * 0.4, 0))
	end
end

-- The glowing row: the playhead while playing or paused, otherwise the chosen start row.
local function glowRow()
	if isPlaying and playRow then
		return playRow
	end
	return sheetSelected
end

local function refreshSheet()
	if glowTween then
		glowTween:Cancel()
		glowTween = nil
	end
	if glowStroke then
		glowStroke.Enabled = false
		glowStroke = nil
	end
	local target = glowRow()
	for i, btn in ipairs(sheetButtons) do
		local on = (i == target)
		local stroke = btn:FindFirstChild("Glow")
		btn.BackgroundColor3 = on and SHEET_GLOW or SHEET_IDLE
		btn.BackgroundTransparency = on and 0.05 or 0.6
		if stroke then
			stroke.Enabled = on
			stroke.Transparency = 0
		end
		if on and stroke then
			glowStroke = stroke
			glowTween = tweenService:Create(
				stroke,
				TweenInfo.new(0.8, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
				{ Transparency = 0.7 }
			)
			glowTween:Play()
		end
	end
	keepRowVisible(target)
end

local function stopPlayback()
	if not isPlaying then
		return
	end
	stopRequested = true
	if heartbeatConn then
		heartbeatConn:Disconnect()
		heartbeatConn = nil
	end
	isPlaying = false
	paused = false
	releaseAllKeys()
	playRow = nil
	refreshControls()
	refreshSheet()
	if guiRefs.status then
		guiRefs.status.TextTransparency = 0.3
		guiRefs.status.Text = "Ready."
	end
end


-- The character the playback started from, and whether they were sitting at the piano then.
local playHumanoid = nil
local playStartedSeated = false

-- False once the player has gotten up from the piano, or the piano's keys have gone.
local function stillAtPiano()
	if playStartedSeated then
		if not playHumanoid or not playHumanoid.Parent or playHumanoid.SeatPart == nil then
			return false
		end
	end
	if inputContext and inputContext.type == "touch" and inputContext.keys then
		local _, sample = next(inputContext.keys)
		if sample and not sample:IsDescendantOf(localPlayer.PlayerGui) then
			return false
		end
	end
	return true
end

local function playbackTick(dt)
	local now = os.clock()
	if not stillAtPiano() then
		stopPlayback()
		setStatus("Stopped  -  you left the piano.")
		return
	end
	local timeline = now - playClock
	local slack = math.min(dt, 0.05) * 0.5
	local events = playEvents

	if guiRefs.status and now - lastStatusAt >= 0.1 then
		lastStatusAt = now
		guiRefs.status.TextTransparency = 0
		guiRefs.status.Text = string.format("Note %d/%d  -  %s",
			math.min(playNextIndex, #events), #events, clockText(timeline))
	end

	local row = math.min(math.max(math.floor(timeline), 0) + 1, #sheetButtons)
	if row >= 1 and row ~= playRow then
		playRow = row
		refreshSheet()
	end

	for key, rel in pairs(releaseAt) do
		if now + slack >= rel.at then
			releaseAt[key] = nil
			if keyDown[key] == rel.id then
				keyDown[key] = nil
				releaseKey(key)
			end
		end
	end

	while playNextIndex <= #events do
		local event = events[playNextIndex]
		if timeline + slack < event.fireAt then
			break
		end
		playNextIndex = playNextIndex + 1
		local releaseTime = playClock + event.fireAt + event.hold
		for _, key in ipairs(event.keys) do
			pendingPress[#pendingPress + 1] = { key = key, release = releaseTime, hold = event.hold, index = playNextIndex - 1 }
		end
	end

	local sent = 0
	while #pendingPress > 0 and sent < CONFIG.chordKeysPerFrame do
		local p = table.remove(pendingPress, 1)
		sent = sent + 1
		if p.release > os.clock() then
			pressAndSchedule(p.key, p.release)
		end
	end

	if playNextIndex > #events and #pendingPress == 0 and next(releaseAt) == nil then
		stopPlayback()
	end
end

-- Starts the playback loop, and never leaves an older loop running next to the new one.
local function connectPlaybackLoop()
	if heartbeatConn then
		heartbeatConn:Disconnect()
	end
	heartbeatConn = runService.Heartbeat:Connect(playbackTick)
end

local function pausePlayback()
	if not isPlaying or paused then
		return
	end
	paused = true
	if heartbeatConn then
		heartbeatConn:Disconnect()
		heartbeatConn = nil
	end
	pausedAt = math.max(os.clock() - playClock, 0)
	-- Chord keys not sent yet belong to an event that is replayed on resume.
	for _, p in ipairs(pendingPress) do
		if p.index and p.index < playNextIndex then
			playNextIndex = p.index
		end
	end
	releaseAllKeys()
	refreshControls()
	setStatus("Paused  -  " .. clockText(pausedAt))
end

local function resumePlayback()
	if not isPlaying or not paused then
		return
	end
	paused = false
	playClock = os.clock() - pausedAt
	lastStatusAt = 0
	connectPlaybackLoop()
	refreshControls()
end

local function startPlayback(fromTime)
	if isPlaying or not currentSong then
		return
	end
	inputContext = probeInputContext()

	local events = getPlayEvents(currentSong)
	local t = math.max(fromTime or 0, 0)
	isPlaying = true
	paused = false
	stopRequested = false
	playNextIndex = firstEventAtOrAfter(events, t)
	playRow = math.floor(t) + 1
	playClock = os.clock() + CONFIG.startDelay - t
	releaseAt = {}
	pendingPress = {}
	lastStatusAt = 0
	local character = localPlayer.Character
	playHumanoid = character and character:FindFirstChildOfClass("Humanoid") or nil
	playStartedSeated = playHumanoid ~= nil and playHumanoid.SeatPart ~= nil
	connectPlaybackLoop()
	refreshControls()
	refreshSheet()
end


-- Moves the playhead to a sheet row. While paused, the pause point moves and playback stays paused.
local function seekToRow(row)
	local t = rowTime(row)
	releaseAllKeys()
	playNextIndex = firstEventAtOrAfter(playEvents, t)
	playRow = row
	sheetSelected = row
	if paused then
		pausedAt = t
		setStatus("Paused  -  " .. clockText(t))
	else
		playClock = os.clock() - t
	end
	refreshSheet()
end

local function onRowPressed(row)
	if isPlaying then
		seekToRow(row)
	else
		sheetSelected = row
		refreshSheet()
	end
end

local function playButtonPressed()
	if not currentSong then
		return
	end
	if paused then
		resumePlayback()
	elseif not isPlaying then
		startPlayback(rowTime(sheetSelected))
	end
end

local function togglePause()
	if not isPlaying then
		return
	end
	if paused then
		resumePlayback()
	else
		pausePlayback()
	end
end

local function playFromStart()
	if not currentSong then
		return
	end
	stopPlayback()
	sheetSelected = 1
	startPlayback(0)
end


-- Builds the note sheet: one row per second of the song, showing the keys played in that second.
local function buildSheet(song)
	for _, btn in ipairs(sheetButtons) do
		btn:Destroy()
	end
	sheetButtons = {}
	if glowTween then
		glowTween:Cancel()
		glowTween = nil
	end
	glowStroke = nil
	playRow = nil
	sheetSelected = 1
	local sheet = guiRefs.sheet
	if not sheet or not song then
		return
	end
	sheet.CanvasPosition = Vector2.new(0, 0)

	local events = getPlayEvents(song)
	local bySecond = {}
	local lastSecond = 0
	for _, event in ipairs(events) do
		local s = math.floor(event.fireAt)
		local previous = bySecond[s]
		bySecond[s] = (previous and (previous .. " ") or "") .. table.concat(event.keys)
		if s > lastSecond then
			lastSecond = s
		end
	end

	for s = 0, lastSecond do
		local index = s + 1
		local btn = Instance.new("TextButton")
		btn.Name = "Row" .. index
		btn.LayoutOrder = index
		btn.Size = UDim2.new(1, -10, 0, SHEET_ROW_H)
		btn.BackgroundColor3 = SHEET_IDLE
		btn.BackgroundTransparency = 0.6
		btn.BorderSizePixel = 0
		btn.AutoButtonColor = false
		btn.Text = string.format("  %d:%02d   %s", math.floor(s / 60), s % 60, bySecond[s] or "-")
		btn.TextColor3 = TEXT_DARK
		btn.TextSize = 11
		btn.Font = Enum.Font.GothamMedium
		btn.TextXAlignment = Enum.TextXAlignment.Left
		btn.TextTruncate = Enum.TextTruncate.AtEnd
		btn.ZIndex = 4
		btn.Parent = sheet

		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, 6)
		corner.Parent = btn

		local glow = Instance.new("UIStroke")
		glow.Name = "Glow"
		glow.Color = SHEET_GLOW_EDGE
		glow.Thickness = 2
		glow.Enabled = false
		glow.Parent = btn

		btn.MouseButton1Click:Connect(function()
			onRowPressed(index)
		end)
		sheetButtons[index] = btn
	end

	if guiRefs.status and not isPlaying then
		setStatus("Tap a row to choose where to start.")
	end
	refreshSheet()
end

local function getGuiParent()
	if gethui then
		local ok, hui = pcall(gethui)
		if ok and hui then return hui end
	end
	return localPlayer:WaitForChild("PlayerGui")
end

local function makeDraggable(frame, handle)
	local dragging = false
	local dragStart, startPos
	local dragDistance = 0

	handle.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			dragDistance = 0
			dragStart = input.Position
			startPos = frame.Position
			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
				end
			end)
		end
	end)

	userInputService.InputChanged:Connect(function(input)
		if not dragging then return end
		if input.UserInputType == Enum.UserInputType.MouseMovement
			or input.UserInputType == Enum.UserInputType.Touch then
			local delta = input.Position - dragStart
			dragDistance = delta.Magnitude
			frame.Position = UDim2.new(
				startPos.X.Scale, startPos.X.Offset + delta.X,
				startPos.Y.Scale, startPos.Y.Offset + delta.Y
			)
		end
	end)

	return function() return dragDistance > 3 end
end

local function buildHeavenBackground(parent)
	local gradient = Instance.new("UIGradient")
	gradient.Color = ColorSequence.new({
		ColorSequenceKeypoint.new(0, HEAVEN_TOP),
		ColorSequenceKeypoint.new(0.5, HEAVEN_MID),
		ColorSequenceKeypoint.new(1, HEAVEN_BOTTOM),
	})
	gradient.Rotation = 90
	gradient.Parent = parent
end

-- The full keyboard in QWERTY rows, like a real keyboard. Number keys also show the Shift
-- symbol the piano uses for sharps. A key lights up only while the script is holding it.
local KB_ROWS = { "1234567890", "qwertyuiop", "asdfghjkl", "zxcvbnm" }
local KB_STAGGER = { 0, 0.5, 0.75, 1.25 }
local CAP_SIZE = 22
local CAP_STEP = 24
local KB_LEFT = 5
local KB_TOP = 6
local KB_EDGE = Color3.fromRGB(196, 206, 224)

local DIGIT_SYMBOL = {}
for symbol, digit in pairs(SHIFT_SYMBOLS) do
	DIGIT_SYMBOL[digit] = symbol
end

local function makeCap(parent, x, y, base)
	local isDigit = base:match("%d") ~= nil
	local cap = {
		white = base,
		sharp = isDigit and DIGIT_SYMBOL[base] or base:upper(),
	}

	local body = Instance.new("Frame")
	body.Position = UDim2.new(0, x, 0, y)
	body.Size = UDim2.new(0, CAP_SIZE, 0, CAP_SIZE)
	body.BackgroundColor3 = KB_EDGE
	body.BorderSizePixel = 0
	body.ZIndex = 4
	body.Parent = parent

	local bodyCorner = Instance.new("UICorner")
	bodyCorner.CornerRadius = UDim.new(0, 5)
	bodyCorner.Parent = body

	local face = Instance.new("Frame")
	face.Size = UDim2.new(1, 0, 1, -2)
	face.BackgroundColor3 = KEY_IDLE
	face.BorderSizePixel = 0
	face.ZIndex = 5
	face.Parent = body

	local faceCorner = Instance.new("UICorner")
	faceCorner.CornerRadius = UDim.new(0, 5)
	faceCorner.Parent = face

	local stroke = Instance.new("UIStroke")
	stroke.Color = SHEET_GLOW_EDGE
	stroke.Thickness = 2
	stroke.Enabled = false
	stroke.Parent = face

	local main = Instance.new("TextLabel")
	main.BackgroundTransparency = 1
	main.Font = Enum.Font.GothamBold
	main.TextSize = 12
	main.TextColor3 = TEXT_DARK
	main.ZIndex = 6
	main.Text = isDigit and base or base:upper()
	main.Parent = face

	if isDigit then
		main.Position = UDim2.new(0, 0, 0, 8)
		main.Size = UDim2.new(1, 0, 1, -8)

		local top = Instance.new("TextLabel")
		top.BackgroundTransparency = 1
		top.Position = UDim2.new(0, 0, 0, 0)
		top.Size = UDim2.new(1, 0, 0, 9)
		top.Font = Enum.Font.GothamBold
		top.TextSize = 8
		top.TextColor3 = ACCENT_DARK
		top.Text = cap.sharp
		top.ZIndex = 6
		top.Parent = face
		cap.top = top
	else
		main.Position = UDim2.new(0, 0, 0, 0)
		main.Size = UDim2.new(1, 0, 1, 0)
	end

	cap.face = face
	cap.main = main
	cap.stroke = stroke
	return cap
end

local function buildKeyboard(container)
	keyBoxes = {}
	for rowIndex, row in ipairs(KB_ROWS) do
		for col = 1, #row do
			local x = KB_LEFT + math.floor((KB_STAGGER[rowIndex] + col - 1) * CAP_STEP)
			local y = KB_TOP + (rowIndex - 1) * CAP_STEP
			local cap = makeCap(container, x, y, row:sub(col, col))
			keyBoxes[cap.white] = cap
			keyBoxes[cap.sharp] = cap
		end
	end
end

local function buildDropdown(parent, anchor)
	local dropdown = Instance.new("Frame")
	dropdown.Name = "Dropdown"
	dropdown.Position = anchor
	dropdown.Size = UDim2.new(1, -20, 0, 30)
	dropdown.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
