	dropdown.ZIndex = 5
	dropdown.Parent = parent

	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, 10)
	corner.Parent = dropdown

	local display = Instance.new("TextButton")
	display.Name = "Display"
	display.Size = UDim2.new(1, 0, 1, 0)
	display.BackgroundTransparency = 1
	display.Text = "Select a song..."
	display.TextColor3 = TEXT_DARK
	display.TextSize = 13
	display.Font = Enum.Font.GothamMedium
	display.TextXAlignment = Enum.TextXAlignment.Left
	display.ZIndex = 6
	display.Parent = dropdown

	local padding = Instance.new("UIPadding")
	padding.PaddingLeft = UDim.new(0, 10)
	padding.Parent = display

	local arrow = Instance.new("TextLabel")
	arrow.AnchorPoint = Vector2.new(1, 0.5)
	arrow.Position = UDim2.new(1, -12, 0.5, 0)
	arrow.Size = UDim2.new(0, 20, 0, 20)
	arrow.BackgroundTransparency = 1
	arrow.Text = "v"
	arrow.TextColor3 = ACCENT_DARK
	arrow.TextSize = 16
	arrow.Font = Enum.Font.GothamBold
	arrow.ZIndex = 6
	arrow.Parent = dropdown

	local list = Instance.new("ScrollingFrame")
	list.Name = "List"
	list.Position = UDim2.new(0, 0, 1, 6)
	list.Size = UDim2.new(1, 0, 0, 0)
	list.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	list.BackgroundTransparency = 0.05
	list.BorderSizePixel = 0
	list.ScrollBarThickness = 4
	list.ScrollBarImageColor3 = ACCENT
	list.AutomaticCanvasSize = Enum.AutomaticSize.Y
	list.ClipsDescendants = true
	list.Visible = false
	list.ZIndex = 10
	list.Parent = dropdown

	local listCorner = Instance.new("UICorner")
	listCorner.CornerRadius = UDim.new(0, 10)
	listCorner.Parent = list

	local layout = Instance.new("UIListLayout")
	layout.Padding = UDim.new(0, 2)
	layout.Parent = list

	local isOpen = false
	local itemHeight = 28
	local itemButtons = {}

	local function refreshSelection()
		for _, item in ipairs(itemButtons) do
			if item.song == currentSong then
				item.button.BackgroundColor3 = ACCENT
				item.button.TextColor3 = TEXT_LIGHT
			else
				item.button.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
				item.button.TextColor3 = TEXT_DARK
			end
		end
	end

	for _, song in ipairs(SONGS) do
		local btn = Instance.new("TextButton")
		btn.Size = UDim2.new(1, 0, 0, itemHeight)
		btn.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
		btn.BackgroundTransparency = 0.1
		btn.BorderSizePixel = 0
		btn.Text = "  " .. song.name
		btn.TextColor3 = TEXT_DARK
		btn.TextSize = 13
		btn.Font = Enum.Font.GothamMedium
		btn.TextXAlignment = Enum.TextXAlignment.Left
		btn.ZIndex = 11
		btn.Parent = list
		local c = Instance.new("UICorner")
		c.CornerRadius = UDim.new(0, 6)
		c.Parent = btn

		btn.MouseButton1Click:Connect(function()
			if isPlaying then
				stopPlayback()
			end
			currentSong = song
			display.Text = song.name
			refreshSelection()
			isOpen = false
			list.Visible = false
			list.Size = UDim2.new(1, 0, 0, 0)
			arrow.Text = "v"
			buildSheet(song)
		end)

		table.insert(itemButtons, { button = btn, song = song })
	end

	display.MouseButton1Click:Connect(function()
		isOpen = not isOpen
		if isOpen then
			list.Size = UDim2.new(1, 0, 0, math.min(#SONGS * 30 + 6, 170))
			list.Visible = true
			arrow.Text = "^"
		else
			list.Visible = false
			list.Size = UDim2.new(1, 0, 0, 0)
			arrow.Text = "v"
		end
	end)
end

